*722→function fmtLog(raw) {
*723→    if(!raw) return "Log empty";
*724→    return raw.split('\n').map(l => {
*725→        if(!l.trim()) return "";
*726→        l = l.replace(/\x1b\[32m/g, '<span class="log-green">')
*727→             .replace(/\x1b\[33m/g, '<span class="log-yellow">')
*728→             .replace(/\x1b\[0m/g, '</span>');
*729→        var m = l.match(/time="(.*?)"\s+level=(\w+)\s+msg="(.*)"/);
*730→        if(m) {
*731→            var ts = new Date(m[1]).toLocaleTimeString();
*732→            var lvl = m[2].toUpperCase();
*733→            var txt = m[3];
*734→            var cls = 'log-info';
*735→            if(lvl==='WARN'||lvl==='WARNING') cls='log-warn';
*736→            if(lvl==='ERROR'||lvl==='FATAL') cls='log-err';
